inline TMST::TMST(const TMST &o)
      : ID(o.ID),
        TRACK_ID(o.TRACK_ID),
        ENVIRONMENT(o.ENVIRONMENT),
        EPOCH(o.EPOCH),
        LATITUDE(o.LATITUDE),
        LONGITUDE(o.LONGITUDE),
        ALTITUDE_M(o.ALTITUDE_M),
        GROUND_SPEED_MPS(o.GROUND_SPEED_MPS),
        VELOCITY_NORTH_MPS(o.VELOCITY_NORTH_MPS),
        VELOCITY_EAST_MPS(o.VELOCITY_EAST_MPS),
        VELOCITY_UP_MPS(o.VELOCITY_UP_MPS),
        HEADING_DEG(o.HEADING_DEG),
        COURSE_DEG(o.COURSE_DEG),
        TURN_RATE_DPS(o.TURN_RATE_DPS),
        VERTICAL_RATE_MPS(o.VERTICAL_RATE_MPS),
        MODEL_ID(o.MODEL_ID),
        PROPAGATION_VALID_UNTIL(o.PROPAGATION_VALID_UNTIL),
        POSITION_UNCERTAINTY_M(o.POSITION_UNCERTAINTY_M),
        INNOVATION_GATE_SIGMA(o.INNOVATION_GATE_SIGMA),
        INNOVATION_GATE_DISTANCE_M(o.INNOVATION_GATE_DISTANCE_M),
        TOLERANCE_M(o.TOLERANCE_M),
        TRACK_STATUS(o.TRACK_STATUS),
        STALE_AFTER_S(o.STALE_AFTER_S),
        DROP_AFTER_S(o.DROP_AFTER_S),
        LAST_UPDATE_EPOCH(o.LAST_UPDATE_EPOCH),
        SOURCE((o.SOURCE) ? new TMSProvenanceT(*o.SOURCE) : nullptr) {
  MODEL_PARAMETERS.reserve(o.MODEL_PARAMETERS.size());
  for (const auto &MODEL_PARAMETERS_ : o.MODEL_PARAMETERS) { MODEL_PARAMETERS.emplace_back((MODEL_PARAMETERS_) ? new TMSModelParameterT(*MODEL_PARAMETERS_) : nullptr); }
  IDENTIFIERS.reserve(o.IDENTIFIERS.size());
  for (const auto &IDENTIFIERS_ : o.IDENTIFIERS) { IDENTIFIERS.emplace_back((IDENTIFIERS_) ? new TMSIdentifierT(*IDENTIFIERS_) : nullptr); }
}

