inline const TMS *GetTMS(const void *buf) {
  return ::flatbuffers::GetRoot<TMS>(buf);
}

inline const TMS *GetSizePrefixedTMS(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<TMS>(buf);
}

inline const char *TMSIdentifier() {
  return "$TMS";
}

inline bool TMSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TMSIdentifier());
}

inline bool SizePrefixedTMSBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TMSIdentifier(), true);
}

template <bool B = false>
inline bool VerifyTMSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<TMS>(TMSIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedTMSBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<TMS>(TMSIdentifier());
}

inline void FinishTMSBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TMS> root) {
  fbb.Finish(root, TMSIdentifier());
}

inline void FinishSizePrefixedTMSBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TMS> root) {
  fbb.FinishSizePrefixed(root, TMSIdentifier());
}

inline std::unique_ptr<TMST> UnPackTMS(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TMST>(GetTMS(buf)->UnPack(res));
}

inline std::unique_ptr<TMST> UnPackSizePrefixedTMS(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TMST>(GetSizePrefixedTMS(buf)->UnPack(res));
}

